typedef struct skcms_Matrix3x3 {
    float vals[3][3];
} skcms_Matrix3x3;

typedef struct skcms_Matrix3x4 {
    float vals[3][4];
} skcms_Matrix3x4;

typedef struct skcms_TransferFunction {
    float g, a,b,c,d,e,f;
} skcms_TransferFunction;

typedef enum skcms_TFType {
    skcms_TFType_Invalid,
    skcms_TFType_sRGBish,
    skcms_TFType_PQish,
    skcms_TFType_HLGish,
    skcms_TFType_HLGinvish,
    skcms_TFType_PQ,
    skcms_TFType_HLG,
} skcms_TFType;

typedef union skcms_Curve {
    struct {
        uint32_t alias_of_table_entries;
        skcms_TransferFunction parametric;
    };
    struct {
        uint32_t table_entries;
        const uint8_t* table_8;
        const uint8_t* table_16;
    };
} skcms_Curve;

typedef struct skcms_A2B {
    skcms_Curve     input_curves[4];
    const uint8_t*  grid_8;
    const uint8_t*  grid_16;
    uint32_t        input_channels;
    uint8_t         grid_points[4];

    skcms_Curve     matrix_curves[3];
    skcms_Matrix3x4 matrix;
    uint32_t        matrix_channels;

    uint32_t        output_channels;
    skcms_Curve     output_curves[3];
} skcms_A2B;

typedef struct skcms_B2A {
    skcms_Curve     input_curves[3];
    uint32_t        input_channels;

    uint32_t        matrix_channels;
    skcms_Curve     matrix_curves[3];
    skcms_Matrix3x4 matrix;

    skcms_Curve     output_curves[4];
    const uint8_t*  grid_8;
    const uint8_t*  grid_16;
    uint8_t         grid_points[4];
    uint32_t        output_channels;
} skcms_B2A;

typedef struct skcms_CICP {
    uint8_t color_primaries;
    uint8_t transfer_characteristics;
    uint8_t matrix_coefficients;
    uint8_t video_full_range_flag;
} skcms_CICP;

typedef struct skcms_ICCProfile {
    const uint8_t* buffer;

    uint32_t size;
    uint32_t data_color_space;
    uint32_t pcs;
    uint32_t tag_count;

    skcms_Curve            trc[3];
    skcms_Matrix3x3        toXYZD50;
    skcms_A2B              A2B;
    skcms_B2A              B2A;
    skcms_CICP             CICP;

    bool                   has_trc;
    bool                   has_toXYZD50;
    bool                   has_A2B;
    bool                   has_B2A;
    bool                   has_CICP;
} skcms_ICCProfile;

typedef enum skcms_AlphaFormat {
    skcms_AlphaFormat_Opaque,
    skcms_AlphaFormat_Unpremul,
    skcms_AlphaFormat_PremulAsEncoded,
} skcms_AlphaFormat;

