// - Parametric (via skcms_TransferFunction stored by value)
// - Table 8-bit (table_entries and table_8)
// - Table 16-bit (table_entries and table_16 as byte stream of 16-bit samples)
// We ensure lifetime of any backing buffers by allocating on the heap and tagging attributes.

skcms_Curve* curve = new skcms_Curve();
unsigned int mode = *FUZZ_PARAM(unsigned int) % 3; // 0=parametric, 1=table8, 2=table16

if (mode == 0) {
    // Parametric variant.
    // Choose a TF source: sRGB, identity, PQ, or HLG.
    unsigned int tf_mode = *FUZZ_PARAM(unsigned int) % 4;
    skcms_TransferFunction tf_tmp = {};
    if (tf_mode == 0) {
        const skcms_TransferFunction* p = skcms_sRGB_TransferFunction();
        tf_tmp = *p; // copy-by-value into our curve
        FUZZ_SET_ATTR_STR(curve, "tf_source", "sRGB");
    } else if (tf_mode == 1) {
        const skcms_TransferFunction* p = skcms_Identity_TransferFunction();
        tf_tmp = *p;
        FUZZ_SET_ATTR_STR(curve, "tf_source", "identity");
    } else if (tf_mode == 2) {
        // PQ: require positive nits; sanitize input.
        float nits = *FUZZ_PARAM(float);
        if (!(nits == nits)) { // NaN guard
            nits = 203.0f; // reasonable default
        }
        if (nits <= 0.0f) { nits = -nits + 0.001f; }
        skcms_TransferFunction_makePQ(&tf_tmp, nits);
        FUZZ_SET_ATTR_STR(curve, "tf_source", "PQ");
    } else {
        // HLG: positive parameters; sanitize inputs.
        float w = *FUZZ_PARAM(float);
        float peak = *FUZZ_PARAM(float);
        float gamma = *FUZZ_PARAM(float);
        if (!(w==w)) w = 203.0f;
        if (!(peak==peak)) peak = 1000.0f;
        if (!(gamma==gamma)) gamma = 1.2f;
        if (w <= 0.0f)    { w     = -w     + 0.001f; }
        if (peak <= 0.0f) { peak  = -peak  + 0.001f; }
        if (gamma <= 0.0f){ gamma = -gamma + 0.001f; }
        skcms_TransferFunction_makeHLG(&tf_tmp, w, peak, gamma);
        FUZZ_SET_ATTR_STR(curve, "tf_source", "HLG");
    }

    // Populate union fields for parametric representation.
    curve->alias_of_table_entries = 0; // distinguish from table variant
    curve->parametric = tf_tmp;

    // Helpful attributes.
    skcms_TFType t = skcms_TransferFunction_getType(&curve->parametric);
    FUZZ_SET_ATTR_INT(curve, "variant", 0);
    FUZZ_SET_ATTR_INT(curve, "tf_type", (int)t);
    FUZZ_SET_ATTR_PTR(curve, "table_backing", nullptr);
} else if (mode == 1) {
    // Table 8-bit variant.
    std::string s = FUZZ_PARAM_STR();
    size_t len = s.size();
    if (len == 0) { len = 1; s = std::string("\x00", 1); }
    if (len > 2048) { len = 2048; }
    uint8_t* buf = new uint8_t[len];
    memcpy(buf, s.data(), len);

    curve->table_entries = (uint32_t)len;
    curve->table_8  = (const uint8_t*)buf;
    curve->table_16 = nullptr;

    FUZZ_SET_ATTR_INT(curve, "variant", 1);
    FUZZ_SET_ATTR_INT(curve, "table_bits", 8);
    FUZZ_SET_ATTR_INT(curve, "table_entries_attr", (int)len);
    FUZZ_SET_ATTR_PTR(curve, "table_backing", (void*)buf);
} else {
    // Table 16-bit variant. Backing is a byte array with even length = entries*2.
    std::string s = FUZZ_PARAM_STR();
    size_t bytes = s.size();
    if (bytes < 2) { bytes = 2; }
    if (bytes > 2048) { bytes = 2048; }
    if ((bytes & 1u) != 0u) { bytes -= 1; }

    uint8_t* buf = new uint8_t[bytes];
    // Fill from seed deterministically.
    for (size_t i = 0; i < bytes; ++i) {
        buf[i] = (uint8_t)s[i % s.size()];
    }

    uint32_t entries = (uint32_t)(bytes / 2u);
    if (entries == 0) { entries = 1; /* should not happen due to bytes>=2 */ }

    curve->table_entries = entries;
    curve->table_8  = nullptr;
    curve->table_16 = (const uint8_t*)buf; // API uses byte pointer for 16-bit table

    FUZZ_SET_ATTR_INT(curve, "variant", 2);
    FUZZ_SET_ATTR_INT(curve, "table_bits", 16);
    FUZZ_SET_ATTR_INT(curve, "table_entries_attr", (int)entries);
    FUZZ_SET_ATTR_PTR(curve, "table_backing", (void*)buf);
}

// Validation: curve allocated; for parametric, TF is valid and copied; for tables, entries>0 and backing buffers persist via heap and tracked by attributes.

