import struct, random

# Generator for arbitrary binary buffer (even length) used by fuzz stub to back 16-bit curve tables.
# The stub uses FUZZ_PARAM_STR() to obtain a byte string which it then:
#  - clamps length to [2, 2048]
#  - forces even length by truncation
#  - if source size is N, fills target buffer[i] = source[i % N]
# So our goal: return an even-length bytes (<=4096) that already contains interesting 16-bit patterns
# to produce meaningful tone curves when interpreted as 16-bit sample tables.
# We'll generate a variety of shapes: identity ramp, gamma-like, sRGB-ish, inverse-sRGB-ish,
# flat lines, steps, spikes, random segments, monotonic but with plateaus, etc.
# We will mix little-endian and big-endian encodings so both interpretations see variety.

MAX_OUT = 4096


def _clamp(n, lo, hi):
    return lo if n < lo else hi if n > hi else n


def _be16(x: int) -> bytes:
    return struct.pack('>H', x & 0xFFFF)


def _le16(x: int) -> bytes:
    return struct.pack('<H', x & 0xFFFF)


def _make_ramp(entries: int, endian: str) -> bytes:
    # 16-bit ramp from 0..65535 inclusive (or to max exclusive depending on entries)
    data = bytearray()
    for i in range(entries):
        v = int(round(i * 65535.0 / max(1, entries - 1)))
        data += _le16(v) if endian == 'le' else _be16(v)
    return bytes(data)


def _make_gamma(entries: int, gamma: float, endian: str) -> bytes:
    data = bytearray()
    for i in range(entries):
        x = i / max(1, entries - 1)
        y = pow(x, gamma)
        v = int(round(y * 65535.0))
        data += _le16(v) if endian == 'le' else _be16(v)
    return bytes(data)


def _make_inv_gamma(entries: int, gamma: float, endian: str) -> bytes:
    return _make_gamma(entries, 1.0 / max(1e-6, gamma), endian)


def _make_steps(entries: int, steps: int, endian: str) -> bytes:
    steps = max(1, steps)
    data = bytearray()
    for i in range(entries):
        s = int(i * steps / max(1, entries))
        v = int(round(s * (65535.0 / max(1, steps - 1)))) if steps > 1 else 0
        data += _le16(v) if endian == 'le' else _be16(v)
    return bytes(data)


def _make_flat(entries: int, level: int, endian: str) -> bytes:
    v = _clamp(level, 0, 65535)
    one = _le16(v) if endian == 'le' else _be16(v)
    return one * entries


def _make_spike(entries: int, pos: int, width: int, level: int, endian: str) -> bytes:
    data = bytearray()
    for i in range(entries):
        inside = (pos <= i < pos + width)
        v = level if inside else 0
        data += _le16(v) if endian == 'le' else _be16(v)
    return bytes(data)


def _make_monotonic_with_plateaus(entries: int, plateau_prob: float, endian: str) -> bytes:
    data = bytearray()
    v = 0
    last = 0
    for i in range(entries):
        if i == 0:
            v = 0
        else:
            if random.random() < plateau_prob:
                v = last
            else:
                inc = random.randint(0, max(1, int(65535 / entries * 4)))
                v = min(65535, last + inc)
        data += _le16(v) if endian == 'le' else _be16(v)
        last = v
    return bytes(data)


def _make_segmented(entries: int, endian: str) -> bytes:
    # Piecewise: dark linear, mid gamma, highlight roll-off
    data = bytearray()
    for i in range(entries):
        x = i / max(1, entries - 1)
        if x < 0.1:
            y = x * 2.5  # boosted darks
        elif x < 0.8:
            y = pow((x - 0.1) / 0.7, 2.2) * 0.7
        else:
            t = (x - 0.8) / 0.2
            y = 0.7 + (1.0 - (1.0 - t) * (1.0 - t)) * 0.3  # smooth to 1
        y = max(0.0, min(1.0, y))
        v = int(round(y * 65535.0))
        data += _le16(v) if endian == 'le' else _be16(v)
    return bytes(data)


def _mix_buffers(chunks):
    # Interleave chunks to add variety while keeping even length
    out = bytearray()
    for chunk in chunks:
        out += chunk
    # Ensure even length
    if len(out) % 2 == 1:
        out = out[:-1]
    return bytes(out)


def generate(seed: int) -> bytes:
    random.seed(seed)

    # Decide total entries (each entry = 2 bytes); target within [2, 2048] bytes as stub clamps there.
    # We'll generate between 16 and 1024 entries (32..2048 bytes) for richer tables.
    entries = random.choice([
        16, 33, 64, 129, 256, 257, 512, 513, 768, 1024
    ])

    endian_primary = random.choice(['le', 'be'])

    # Build a set of chunks emphasizing different behaviors.
    chunks = []

    # Identity or near-identity ramp
    chunks.append(_make_ramp(entries // 4, endian_primary))

    # Gamma curves (common: 2.2, 1.8, 2.4)
    gamma_values = [2.2, 1.8, 2.4, 1.0]
    chunks.append(_make_gamma(max(4, entries // 8), random.choice(gamma_values), endian_primary))

    # Inverse gamma to simulate decode/encode curves
    inv_g = random.choice([2.2, 1.8, 2.4])
    chunks.append(_make_inv_gamma(max(4, entries // 8), inv_g, endian_primary))

    # Steps and flat regions for LUT-like tables
    chunks.append(_make_steps(max(4, entries // 16), random.choice([4, 8, 16, 32]), endian_primary))
    flat_level = random.randint(0, 65535)
    chunks.append(_make_flat(max(2, entries // 32), flat_level, endian_primary))

    # A spike to test local non-monotonicity handling (though tables need not be monotonic in this stub)
    width = max(1, entries // 64)
    pos = random.randint(0, max(0, entries // 4 - width))
    chunks.append(_make_spike(entries // 4, pos, width, random.randint(0, 65535), endian_primary))

    # Monotonic with plateaus
    chunks.append(_make_monotonic_with_plateaus(entries // 8, plateau_prob=0.4, endian=endian_primary))

    # Segmented tone-curve
    chunks.append(_make_segmented(entries // 8, endian_primary))

    buf = _mix_buffers(chunks)

    # Optionally append a block with opposite endianness to exercise consumers that might read BE/LE
    if random.random() < 0.5:
        other_endian = 'be' if endian_primary == 'le' else 'le'
        extra = _make_gamma(max(4, entries // 8), random.choice([0.45, 0.55, 1.2, 2.6]), other_endian)
        buf = _mix_buffers([buf, extra])

    # Ensure size constraints: at least 2 bytes, even length, and <= 2048 bytes preferred by stub, but
    # we can return up to 4096; the stub will clamp to 2048 if needed. We'll cap to 2048 to avoid truncation.
    if len(buf) < 2:
        buf += b"\x00\x00"
    if len(buf) % 2 == 1:
        buf = buf[:-1]
    if len(buf) > 2048:
        buf = buf[:2048]

    return bytes(buf)
